import type {BuildCapture,MmoProfileRole} from '@tof-hub/contracts';
import type {MmoCurve} from '@tof-hub/game-domain';
import type {BuildCatalog,LocalizedName,ProfileCosmetic} from '../types';
import type {BrainfieldStatNode} from '../../datamine/handbook/brainfield-domain';

/** Generated by scripts/generators/build-mmo-card.cjs (game-data/build-mmo-page.json); provenance in docs/imports.md. */
export interface MmoGeneratedCatalog {
  schemaVersion:1;
  labels:Record<'fixedMode'|'regularMode'|'fixedModeDescription'|'regularModeDescription'|'equipmentTier'|'expansionStats'|'randomStats'|'baseStats',LocalizedName>;
  panels:{special:string[];elements:{element:string;attack:string;resistance:string}[];basic:string[]};
  resistanceFormula?:{expression:string;k:number;observed:{resistance:number;reduction:number}};
  critFormula?:{source:string;denominators:Record<string,number>};
  attributes:Record<string,{name:LocalizedName|null;icon:string|null;percent:boolean;description?:LocalizedName|null}>;
  slots:{id:string;slot:string;name:LocalizedName|null;icon:string|null;frame:string|null;cardBanks:number;seasonCardBanks:number}[];
  gear:MmoGearItem[];
  pools:Record<string,string[]>;
  randomStats:Record<string,{attribute:string;maxPerItem:number;ranges:Record<string,{base:number;min:number;max:number}>}>;
  cards:MmoCard[];
  /** Level coefficient curves of expansion-card base stats by attribute (Value already applied). */
  cardCoefficients:Record<string,MmoCurve>;
  thresholds:{prop:string;attribute:string;reference?:string;levels:{level:number;value:number;description:LocalizedName|null}[]}[];
  weapons:MmoWeapon[];
  /** `inheritance[advance]`: PlayerModifyCoefficient of the owner's average base ATK (PetAdvanceDataTable_MMO); null = no row. */
  pets:{id:string;name:LocalizedName|null;icon:string|null;portrait:string|null;element:string;maxLevel:number;maxAdvance:number;levels:[number,number,number][];inheritance?:(number|null)[]}[];
  petModules?:MmoPetModule[];
  petModuleLimits?:Record<string,({stars:number;slots:number;load:number}|null)[]>;
  seasons:{index:number;name:LocalizedName|null;editorial?:boolean}[];
  foods:{id:string;name:LocalizedName;icon:string|null;rarity:string}[];
  /** Vera dishes with an MMO ATK% buff (percent units as in food-mmo, e.g. 1 = +1%). */
  potions:{id:string;name:LocalizedName;icon:string|null;rarity:string;atkPercent:number|null}[];
  brainfield:{name:LocalizedName;maximum:number;nodes:{id:string;kind:string;name:LocalizedName|null;maxLevel:number;icon:string|null}[]}[];
  /** MMO-client avatars and frames the Global cosmetics catalog lacks (merged with build-page.json by the route). */
  avatars?:ProfileCosmetic[];avatarFrames?:ProfileCosmetic[];
}
export interface MmoGearItem {id:string;slot:string;name:LocalizedName|null;
  /** Resonance of a guaranteed-pool variant (build-page roleResonances id) and the name without its variant suffix. */
  role?:'dps'|'tank'|'healer'|'balance';baseName?:LocalizedName;
 icon:string|null;quality:string;season:number;grade:number;tier:number;maxEnhancement:number;
  base:{prop:string;value:number;perLevel:number|null}[];pool:string|null}
export interface MmoCard {id:string;name:LocalizedName|null;icon:string|null;quality:string;season:number;exclusive:boolean;maxStars:number;maxSuit:number;slots:string[];
  description:LocalizedName|null;params:{value:number;curve:MmoCurve|null}[];
  /** Base stats: per-level factor for each star level 0…maxStars. */
  stats:{prop:string;values:number[]}[]}
export interface MmoWeapon {id:string;weaponId:string;name:LocalizedName;weapon:LocalizedName;elements:string[];role:string;roleIcon:string|null;icon:string|null;rarity:string;season:number|null;
  advancements:{star:number;combatStrength:number;description:LocalizedName|null}[]}
export interface MmoPetModule {id:string;typeId:string;level:number;load:number;name:LocalizedName|null;description:LocalizedName|null;icon:string|null;exclusivePets:string[];elements:string[]}

/** The generated MMO data plus the shared card presentation (cosmetics, artworks, element icons) of the Build catalog. */
export type MmoBuildCatalog=MmoGeneratedCatalog&Pick<BuildCatalog,'artworks'|'elementIcons'|'titles'|'titleStyles'>&{roleResonances:BuildCatalog['roleResonances']['items']}&{avatars:ProfileCosmetic[];avatarFrames:ProfileCosmetic[];demoCharacterTitle?:string;
  /** Per-level attribute rows of every Brainfield node (handbook/mmo-brainfield.json projection) for the stat sums. */
  brainfieldStats?:BrainfieldStatNode[]};

export interface MmoGearDraft {itemId:string;rolls:{prop:string;value:number|null}[];card:{id:string;stars:number}|null}
export type MmoWeaponMode='fixed'|'regular';
export interface MmoBuildDraft {
  version:1;mode:'mmo';updatedAt?:string;
  /** The sample card from "Test data". */
  demo?:true;
  profile:{name:string;uid:string;level:number;cs:number|null;season:number|null;crew:string;characterTitle:string;signature:string;avatarId:string;avatarFrameId:string};
  art:{id:string;zoom:number;x:number;y:number;offsetX?:number;offsetY?:number};
  /** In-game attribute panel values by attribute id; percent attributes are stored as fractions; null = unknown. */
  stats:Record<string,number|null>;
  /** Keyed by MMO card slot id (helmet … reactor). */
  gear:Record<string,MmoGearDraft>;
  weapons:{id:string;stars:number}[];
  weaponMode:MmoWeaponMode|null;
  /** Brainfield node / special-skill id → level. */
  brainfield:Record<string,number>;
  pet:{id:string;level:number;inheritedAttack:number|null;stars?:number;modules?:{slot:number;id:string}[]}|null;
  /** One dish and one ATK% dish can be active together. */
  consumables:{food:string;potion:string};
  /** Header role, the player's choice (saved builds are one per role); absent = the weapon resonance. */
  role?:MmoProfileRole;
  /** The server-signed capture of an imported card: a public save stores only it, so it needs the unedited card. */
  source?:MmoCaptureSource;
}
export interface MmoCaptureSource {capture:BuildCapture;digest:string;signature:string}
